it('returns a required location rejection instead of executing missing input', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'weather',
      description: 'Weather forecast',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    },
    async input => `Forecast: ${JSON.stringify(input)}`
  );
  const response = await registry.execute('weather', {});
  expect({result: response.result, containsForecast: response.result.includes('Forecast:')}).toEqual({
    result: expect.stringMatching(/required.*location|location.*required/i),
    containsForecast: false,
  });
});
